package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static ge.opensoft.openservice.EmployeeCasesAcceptance.result;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
import java.util.concurrent.*;
import java.net.http.HttpResponse;

final class GroupApprovalsAcceptance {
 static final String POLICY="/api/openservice/approval-policies/";
 static Map<String,Object> seed(Store store,String prefix)throws Exception {try(var db=store.open()){PlatformFoundationTest.bind(db);var f=map("a",prefix+"A","b",prefix+"B","c",prefix+"C","d",prefix+"D");for(String key:List.of("a","b","c","d")){Service.createAccount(db,map("name",f.get(key),"role","agent","password",PASSWORD));f.put(key+"Id",RecordAccess.owner(db,f.get(key).toString()));}String first=Service.create(db,"sys_user_group",map("short_description","Technical review team"),"admin").get("sys_id").toString(),second=Service.create(db,"sys_user_group",map("short_description","Service owner review team"),"admin").get("sys_id").toString();for(String key:List.of("aId","bId"))GroupMembers.change(db,first,db.viewerId,map("user_id",f.get(key)),true);for(String key:List.of("cId","dId"))GroupMembers.change(db,second,db.viewerId,map("user_id",f.get(key)),true);String table="u_group_"+id();var definition=new LinkedHashMap<>(Service.schema(db,"incident"));definition.putAll(map("version",0,"label","Grouped service cases","prefix","GRC","transition_rules",map()));Configuration.install(db,ConfigurationAcceptance.bundle(table,definition),db.viewerId,false);GroupApprovals.configure(db,table,map("version",1,"target_state","2","groups",List.of(first,second)));String record=Service.create(db,table,map("short_description","Review staged service work"),"admin").get("sys_id").toString();f.putAll(map("table",table,"id",record,"g1",first,"g2",second));db.connection.commit();return f;}}
 static String reviews(Map<String,Object> f){return "/api/openservice/records/"+f.get("table")+"/"+f.get("id")+"/approvals";}
 static String stage(Map<String,Object> f){return reviews(f).replace("/approvals","/approval-stage");}
 static String record(Map<String,Object> f){return "/api/now/table/"+f.get("table")+"/"+f.get("id");}
 static int revision(WorkflowSupport h,Map<String,Object> f)throws Exception {return Integer.parseInt(result(h.get(record(f),auth("admin"))).get("sys_mod_count").toString());}
 static Map<String,Object> requestBody(WorkflowSupport h,Map<String,Object> f)throws Exception {return map("expected_revision",revision(h,f),"target_state","2","reason","Independent review before work starts");}
 static Map<String,Object> request(WorkflowSupport h,Map<String,Object> f)throws Exception {var response=h.json("POST",stage(f),requestBody(h,f),auth("admin"));assertEquals(201,response.statusCode(),html(response));return result(response);}
 static String pending(WorkflowSupport h,Map<String,Object> f,String key)throws Exception {try(var db=h.store.open()){return db.one("SELECT approval_id FROM os_approval WHERE record_id=? AND approver_name=? AND status='requested' ORDER BY sequence DESC",f.get("id"),f.get(key)).get("approval_id").toString();}}
 static HttpResponse<byte[]> decision(WorkflowSupport h,Map<String,Object> f,String key,String approval,String outcome)throws Exception {return h.json("POST",reviews(f)+"/"+approval+"/decision",map("decision",outcome,"comment","Review outcome"),auth(f.get(key).toString()));}
 static String decide(WorkflowSupport h,Map<String,Object> f,String key,String outcome)throws Exception {String approval=pending(h,f,key);var response=decision(h,f,key,approval,outcome);assertEquals(200,response.statusCode(),html(response));return approval;}
 static Map<String,Object> requirement(WorkflowSupport h,Map<String,Object> f,String actor)throws Exception {var response=h.get(reviews(f),auth(actor));assertEquals(200,response.statusCode(),html(response));return ApprovalRequirementsAcceptance.target(parsed(response),"2");}
 static void run(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Stages");try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,f.get("g2").toString(),db.viewerId,map("user_id",f.get("aId")),true);db.connection.commit();}assertEquals(200,h.get(POLICY+f.get("table"),auth("admin")).statusCode());assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());var first=request(h,f);assertEquals(2,first.get("requested"));assertEquals(0,first.get("stage"));String unused=pending(h,f,"b"),a=decide(h,f,"a","approved");assertEquals(409,decision(h,f,"b",unused,"approved").statusCode());assertEquals(1,requirement(h,f,"admin").get("qualifying"));assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());var second=request(h,f);assertEquals(1,second.get("stage"));String c=decide(h,f,"c","approved");assertEquals(true,requirement(h,f,"admin").get("approval_satisfied"));assertEquals(false,requirement(h,f,f.get("a").toString()).get("approval_satisfied"));assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth(f.get("a").toString())).statusCode());assertEquals(409,h.json("PATCH",record(f),map("state","2","description","Unreviewed"),auth("admin")).statusCode());assertEquals(409,h.json("POST",stage(f),requestBody(h,f),auth("admin")).statusCode());new Store(h.environment);assertEquals(true,requirement(h,f,"admin").get("approval_satisfied"));assertEquals(200,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(4,db.count("SELECT COUNT(*) FROM os_approval_group"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=? AND status='withdrawn'",f.get("id")));assertEquals(2,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='approval.group_completed'",f.get("id")));}assertEquals(200,h.json("PATCH",record(f),map("description","Normal edit after transition"),auth("admin")).statusCode());
 }
 static void configuration(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Config");String api=POLICY+f.get("table");assertEquals(401,h.get(api,null).statusCode());assertEquals(403,h.get(api,auth(f.get("a").toString())).statusCode());assertEquals(405,h.json("DELETE",api,map(),auth("admin")).statusCode());assertEquals(400,h.get(api+"?x=1",auth("admin")).statusCode());assertEquals(400,h.get(api+"?x=1&x=2",auth("admin")).statusCode());assertEquals(404,h.get(POLICY+"u_missing",auth("admin")).statusCode());assertEquals(400,h.get(POLICY+"sys_user_group",auth("admin")).statusCode());
  for(Object groups:List.of("bad",Collections.nCopies(6,f.get("g1")),List.of(f.get("g1"),f.get("g1")),List.of(1),List.of("bad"))){var response=h.json("POST",api,map("version",2,"target_state","2","groups",groups),auth("admin"));assertEquals(400,response.statusCode(),html(response));}
  for(Object body:List.of(map(),map("version","2","target_state","2","groups",List.of()),map("version",2,"target_state","missing","groups",List.of()),map("version",2,"target_state","1","groups",List.of(f.get("g1")))))assertEquals(400,h.json("POST",api,body,auth("admin")).statusCode());assertEquals(409,h.json("POST",api,map("version",0,"target_state","2","groups",List.of()),auth("admin")).statusCode());assertEquals(404,h.json("POST",api,map("version",2,"target_state","2","groups",List.of(id())),auth("admin")).statusCode());
  Map<String,Object> schema;try(var db=h.store.open()){schema=Service.schema(db,f.get("table").toString());}for(Object value:List.of(List.of(),"invalid")){var d=new LinkedHashMap<>(schema);d.put("transition_rules",map("2",map("approval_groups",value)));assertEquals(400,h.json("POST","/api/openservice/configuration",ConfigurationAcceptance.bundle(f.get("table").toString(),d),auth("admin")).statusCode());}var both=new LinkedHashMap<>(schema);both.put("transition_rules",map("2",map("approval_groups",List.of(f.get("g1")),"min_approvals",1)));assertEquals(400,h.json("POST","/api/openservice/configuration",ConfigurationAcceptance.bundle(f.get("table").toString(),both),auth("admin")).statusCode());
  assertEquals(200,h.json("POST",api,map("version",2,"target_state","2","groups",List.of()),auth("admin")).statusCode());assertFalse(requirement(h,f,"admin").containsKey("group_stages"));assertEquals(200,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());
 }
 static void rejection(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Reject");request(h,f);decide(h,f,"a","rejected");assertEquals(409,h.json("POST",stage(f),requestBody(h,f),auth("admin")).statusCode());assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());assertEquals("rejected",objects(requirement(h,f,"admin").get("group_stages")).getFirst().get("status"));assertEquals(200,h.json("PATCH",record(f),map("description","Revised proposal after rejection"),auth("admin")).statusCode());request(h,f);decide(h,f,"a","approved");request(h,f);decide(h,f,"c","rejected");assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=? AND status='requested'",f.get("id")));}
 }
 static void manual(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Manual");var body=requestBody(h,f);body.put("approver",f.get("c"));assertEquals(400,h.json("POST",reviews(f),body,auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=?",f.get("id")));}body.put("approver",f.get("a"));assertEquals(201,h.json("POST",reviews(f),body,auth("admin")).statusCode());String approval=pending(h,f,"a");assertEquals(400,h.json("POST",reviews(f)+"/"+approval+"/delegate",map("approver",f.get("c")),auth(f.get("a").toString())).statusCode());assertEquals(200,h.json("POST",reviews(f)+"/"+approval+"/delegate",map("approver",f.get("b")),auth(f.get("a").toString())).statusCode());assertEquals(200,decision(h,f,"b",approval,"approved").statusCode());body.put("approver",f.get("c"));assertEquals(201,h.json("POST",reviews(f),body,auth("admin")).statusCode());decide(h,f,"c","approved");assertEquals(200,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());
 }
 static void revocation(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Revoked");request(h,f);String a=decide(h,f,"a","approved");request(h,f);String c=decide(h,f,"c","approved");try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,f.get("g1").toString(),db.viewerId,map("user_id",f.get("aId")),false);db.connection.commit();}assertEquals(false,requirement(h,f,"admin").get("approval_satisfied"));assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals("group_policy_unsatisfied",ApprovalDiagnostics.inspect(db,db.viewerId,a).get("reason"));GroupMembers.change(db,f.get("g1").toString(),db.viewerId,map("user_id",f.get("aId")),true);db.connection.commit();}assertEquals(true,requirement(h,f,"admin").get("approval_satisfied"));try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",f.get("aId"));db.connection.commit();}assertEquals(false,requirement(h,f,"admin").get("approval_satisfied"));request(h,f);decide(h,f,"b","approved");assertEquals(1,requirement(h,f,"admin").get("qualifying"));assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());request(h,f);decide(h,f,"d","approved");assertEquals(true,requirement(h,f,"admin").get("approval_satisfied"));
 }
 static void pendingOrder(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Order");request(h,f);decide(h,f,"a","approved");request(h,f);String old=pending(h,f,"c");try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE user_id=?",f.get("aId"));db.connection.commit();}assertEquals(400,decision(h,f,"c",old,"approved").statusCode());request(h,f);decide(h,f,"b","approved");assertEquals(409,decision(h,f,"c",old,"approved").statusCode());assertEquals(200,h.json("POST",reviews(f)+"/"+old+"/withdraw",map("comment","Earlier approval replaced"),auth("admin")).statusCode());String other=pending(h,f,"d");assertEquals(200,h.json("POST",reviews(f)+"/"+other+"/withdraw",map("comment","Earlier approval replaced"),auth("admin")).statusCode());request(h,f);decide(h,f,"c","approved");assertEquals(true,requirement(h,f,"admin").get("approval_satisfied"));
 }
 static void authority(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Authority");String url=stage(f);h.account("GroupReadOnly","reader");assertEquals(401,h.json("POST",url,requestBody(h,f),null).statusCode());assertEquals(403,h.json("POST",url,requestBody(h,f),auth("GroupReadOnly")).statusCode());assertEquals(405,h.get(url,auth("admin")).statusCode());assertEquals(400,h.json("POST",url+"?x=1",requestBody(h,f),auth("admin")).statusCode());for(Object body:List.of(map(),map("expected_revision","0","target_state","2","reason","Test")))assertEquals(400,h.json("POST",url,body,auth("admin")).statusCode());assertEquals(409,h.json("POST",url,map("expected_revision",1,"target_state","2","reason","Stale"),auth("admin")).statusCode());
  try(var db=h.store.open()){PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,f.get("table").toString(),f.get("id").toString()),db.viewerId,map("visibility","private","owner_id",db.viewerId));db.connection.commit();}assertEquals(409,h.json("POST",url,requestBody(h,f),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=?",f.get("id")));PlatformFoundationTest.bind(db);RecordAccess.change(db,Service.record(db,f.get("table").toString(),f.get("id").toString()),db.viewerId,map("visibility","workspace","owner_id",""));db.connection.commit();}
  request(h,f);String a=pending(h,f,"a");try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,f.get("g1").toString(),db.viewerId,map("user_id",f.get("aId")),false);db.connection.commit();}assertEquals(400,decision(h,f,"a",a,"approved").statusCode());decide(h,f,"b","approved");request(h,f);decide(h,f,"c","approved");try(var db=h.store.open()){PlatformFoundationTest.bind(db);assertEquals("qualifying",ApprovalDiagnostics.inspect(db,db.viewerId,db.one("SELECT approval_id FROM os_approval WHERE record_id=? AND approver_name=?",f.get("id"),f.get("b")).get("approval_id").toString()).get("reason"));db.update("DELETE FROM os_record WHERE sys_id=?",f.get("g1"));db.connection.commit();}var progress=objects(requirement(h,f,"admin").get("group_stages"));assertEquals("Unavailable review team",progress.getFirst().get("group_name"));assertEquals(false,requirement(h,f,"admin").get("approval_satisfied"));
 }
 static void persistence(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Persist");String table=f.get("table").toString();var creation=h.json("POST","/api/now/table/"+table,map("short_description","Unreviewed protected creation","state","2"),auth("admin"));assertEquals(400,creation.statusCode());assertTrue(html(creation).contains("initial state"),html(creation));for(String dry:List.of("true","false"))assertEquals(400,h.json("POST","/api/openservice/import/"+table+"?dry_run="+dry,map("result",List.of(map("sys_id",id(),"short_description","Imported protected state","state","2","priority","3"))),auth("admin")).statusCode());try(var db=h.store.open()){PlatformFoundationTest.bind(db);var item=Service.record(db,table,f.get("id").toString());object(item.get("data")).put("state","2");assertEquals(409,assertThrows(Failure.class,()->Service.save(db,item)).status);item.put("sys_id",id());assertEquals(409,assertThrows(Failure.class,()->Service.insert(db,item)).status);db.connection.rollback();assertEquals(1,db.count("SELECT COUNT(*) FROM os_record WHERE \"table\"=?",table));}
  request(h,f);String pending=pending(h,f,"a");assertEquals(200,h.json("POST",POLICY+table,map("version",2,"target_state","2","groups",List.of(f.get("g2"),f.get("g1"))),auth("admin")).statusCode());assertEquals(409,decision(h,f,"a",pending,"approved").statusCode());assertEquals(0,requirement(h,f,"admin").get("qualifying"));request(h,f);decide(h,f,"c","approved");
 }
 static void concurrency(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Concurrent");var body=requestBody(h,f);try(var pool=Executors.newFixedThreadPool(2)){var latch=new CountDownLatch(1);var a=pool.submit(()->{latch.await();return h.json("POST",stage(f),body,auth("admin")).statusCode();});var b=pool.submit(()->{latch.await();return h.json("POST",stage(f),body,auth("admin")).statusCode();});latch.countDown();assertEquals(Set.of(201,409),Set.of(a.get(),b.get()));}
  String a=pending(h,f,"a"),b=pending(h,f,"b");try(var pool=Executors.newFixedThreadPool(2)){var latch=new CountDownLatch(1);var one=pool.submit(()->{latch.await();return decision(h,f,"a",a,"approved").statusCode();});var two=pool.submit(()->{latch.await();return decision(h,f,"b",b,"approved").statusCode();});latch.countDown();assertEquals(Set.of(200,409),Set.of(one.get(),two.get()));}assertEquals(1,requirement(h,f,"admin").get("qualifying"));try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=?",f.get("id")));}
 }
 static void limits(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Bounded");try(var db=h.store.open()){String password=db.one("SELECT password FROM os_user WHERE name=?",f.get("a")).get("password").toString();for(int n=0;n<99;n++){String user=id();db.update("INSERT INTO os_user(user_id,name,role,password) VALUES(?,?,'agent',?)",user,"GroupLimit"+n,password);db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",f.get("g1"),user);}db.connection.commit();}assertEquals(400,h.json("POST",stage(f),requestBody(h,f),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_approval WHERE record_id=?",f.get("id")));db.update("DELETE FROM os_group_member WHERE group_id=?",f.get("g1"));db.connection.commit();}assertEquals(409,h.json("POST",stage(f),requestBody(h,f),auth("admin")).statusCode());
 }
 static void legacy(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Legacy");assertEquals(200,h.json("POST",POLICY+f.get("table"),map("version",2,"target_state","2","groups",List.of()),auth("admin")).statusCode());assertEquals(400,h.json("POST",stage(f),requestBody(h,f),auth("admin")).statusCode());var body=requestBody(h,f);body.put("approver",f.get("a"));assertEquals(201,h.json("POST",reviews(f),body,auth("admin")).statusCode());String a=pending(h,f,"a");assertEquals(200,h.json("POST",reviews(f)+"/"+a+"/delegate",map("approver",f.get("b")),auth(f.get("a").toString())).statusCode());assertEquals(200,decision(h,f,"b",a,"approved").statusCode());assertFalse(requirement(h,f,"admin").containsKey("group_stages"));
 }
 static void corruptEvidence(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Evidence");request(h,f);String a=pending(h,f,"a");try(var db=h.store.open()){db.update("DELETE FROM os_approval_group WHERE approval_id=?",a);db.connection.commit();}assertEquals(400,decision(h,f,"a",a,"approved").statusCode());String b=decide(h,f,"b","approved");try(var db=h.store.open()){db.update("UPDATE os_approval_group SET group_id=? WHERE approval_id=?",f.get("g2"),b);db.connection.commit();}assertEquals(0,requirement(h,f,"admin").get("qualifying"));assertEquals(409,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());
 }

 static void reauthentication(WorkflowSupport h)throws Exception {
  var f=seed(h.store,"Reauth");try(var db=h.store.open()){PlatformFoundationTest.bind(db);var definition=Service.schema(db,f.get("table").toString());object(object(definition.get("transition_rules")).get("2")).put("reauthenticate",true);Configuration.install(db,ConfigurationAcceptance.bundle(f.get("table").toString(),definition),db.viewerId,false);db.connection.commit();}request(h,f);String a=pending(h,f,"a");assertEquals(400,decision(h,f,"a",a,"approved").statusCode());assertEquals(400,h.json("POST",reviews(f)+"/"+a+"/decision",map("decision","approved","comment","Current group evidence","current_password","WrongPassword123"),auth(f.get("a").toString())).statusCode());assertEquals(200,h.json("POST",reviews(f)+"/"+a+"/decision",map("decision","approved","comment","Current group evidence","current_password",PASSWORD),auth(f.get("a").toString())).statusCode());request(h,f);String c=pending(h,f,"c");try(var db=h.store.open()){PlatformFoundationTest.bind(db);GroupMembers.change(db,f.get("g2").toString(),db.viewerId,map("user_id",f.get("cId")),false);db.connection.commit();}assertEquals(400,h.json("POST",reviews(f)+"/"+c+"/decision",map("decision","approved","comment","Removed member","current_password",PASSWORD),auth(f.get("c").toString())).statusCode());assertEquals(1,requirement(h,f,"admin").get("qualifying"));assertEquals(200,h.json("POST",reviews(f)+"/"+pending(h,f,"d")+"/decision",map("decision","approved","comment","Current owner group evidence","current_password",PASSWORD),auth(f.get("d").toString())).statusCode());assertEquals(200,h.json("PATCH",record(f),map("state","2"),auth("admin")).statusCode());
 }

}
